import{_ as o,C as i,o as r,c as d,al as l,E as e,w as n}from"./chunks/framework.BawR2jEz.js";const C=JSON.parse('{"title":"Начало работы","description":"Обзор возможностей exDoc — модуля для OpenCart 3, превращающего CMS в платформу для создания контентных страниц и макетов.","frontmatter":{"title":"Начало работы","description":"Обзор возможностей exDoc — модуля для OpenCart 3, превращающего CMS в платформу для создания контентных страниц и макетов."},"headers":[],"relativePath":"getting-started/index.md","filePath":"getting-started/index.md"}'),c={name:"getting-started/index.md"};function m(p,a,u,_,S,h){const t=i("FeatureCard"),s=i("FeatureGrid");return r(),d("div",null,[a[0]||(a[0]=l('<h1 id="начало-работы" tabindex="-1">Начало работы <a class="header-anchor" href="#начало-работы" aria-label="Permalink to &quot;Начало работы&quot;">​</a></h1><h2 id="что-такое-exdoc" tabindex="-1">Что такое exDoc <a class="header-anchor" href="#что-такое-exdoc" aria-label="Permalink to &quot;Что такое exDoc&quot;">​</a></h2><p>exDoc — модуль для OpenCart 3, который превращает стандартную CMS интернет-магазина в полноценную платформу для создания контентных страниц и макетов. С exDoc вы можете:</p><ul><li>Создавать произвольные страницы с уникальным дизайном</li><li>Переопределять стандартные шаблоны OpenCart (товары, категории, производители)</li><li>Строить блочные макеты с SCSS-стилизацией</li><li>Управлять контентом через систему рубрик, категорий и документов</li><li>Использовать 28 типов полей для структурирования данных</li></ul><h2 id="преимущества" tabindex="-1">Преимущества <a class="header-anchor" href="#преимущества" aria-label="Permalink to &quot;Преимущества&quot;">​</a></h2>',5)),e(s,null,{default:n(()=>[e(t,{icon:"🧩",title:"Компонентная архитектура",details:"Блоки поддерживают вложенные компоненты любого уровня. Собирайте сложные макеты из простых строительных блоков."}),e(t,{icon:"📦",title:"Переносимость между проектами",details:"Экспортируйте блоки, компоненты, рубрики и шаблоны — переносите готовые решения на новые сайты в один клик."}),e(t,{icon:"⚡",title:"Управление ресурсами",details:"При отключении блока его стили и скрипты исключаются из сборки. Неактивные блоки не влияют на производительность."}),e(t,{icon:"🎨",title:"SCSS-компиляция на сервере",details:"Стили компилируются на сервере — не нужен Node.js или webpack. Правьте SCSS прямо из админки с sourcemap для отладки."}),e(t,{icon:"🔄",title:"Переопределение шаблонов OpenCart",details:"Замените любой шаблон OpenCart без OCMOD — создайте рубрику, привяжите к маршруту и напишите свой Twig-шаблон."}),e(t,{icon:"📋",title:"28 типов кастомных полей",details:"Текст, изображения, таблицы, формы, связи с товарами — настраиваются через интерфейс без PHP и SQL."}),e(t,{icon:"🖼️",title:"SVG-спрайты",details:"Единый реестр SVG-иконок с импортом из кода. Все спрайты в одном месте с удобным поиском и вставкой."}),e(t,{icon:"🌐",title:"Мультиязычность",details:"Встроенная поддержка нескольких языков на уровне всех сущностей — блоков, документов, категорий и полей."}),e(t,{icon:"🎯",title:"Глобальные переменные стилей",details:"Единые дизайн-токены: цвета, шрифты, отступы. Меняете в одном месте — применяется во всех блоках."}),e(t,{icon:"🔒",title:"Гранулярные права доступа",details:"Гибкая система ролей: верстальщику — блоки, контент-менеджеру — документы. Без полного доступа к админке."}),e(t,{icon:"📐",title:"Рубрики с настраиваемыми полями",details:"Рубрики определяют структуру данных для документов и категорий. Новости, статьи, акции — каждая со своим набором полей."}),e(t,{icon:"🖥️",title:"Удобная админ-панель",details:"Vue 3 SPA с вкладками, drag & drop и глобальным поиском по всем сущностям — по имени, хэштегу или содержимому шаблонов."}),e(t,{icon:"📁",title:"Встроенный файловый менеджер",details:"Загрузка, просмотр и выбор файлов — без сторонних решений или стандартного файл-менеджера OpenCart."}),e(t,{icon:"⚙️",title:"Пресеты полей",details:"Сохраняйте наборы полей как пресеты и применяйте к другим сущностям в один клик. Шаблон, стили и скрипты — всё переносится."}),e(t,{icon:"🌍",title:"Глобальные поля",details:"Поля на уровне всего проекта — контакты, реквизиты, ссылки на соцсети. Доступны на любой странице и в любом блоке."}),e(t,{icon:"🚀",title:"Многоуровневое кэширование",details:"Кэш запросов, SEO-путей, Twig-шаблонов и фидов. Работает автоматически, учитывает язык и магазин."})]),_:1}),a[1]||(a[1]=l('<h2 id="часто-задаваемые-вопросы" tabindex="-1">Часто задаваемые вопросы <a class="header-anchor" href="#часто-задаваемые-вопросы" aria-label="Permalink to &quot;Часто задаваемые вопросы&quot;">​</a></h2><details class="details custom-block"><summary>Нужен ли Node.js для работы exDoc?</summary><p>Нет. SCSS-стили компилируются на сервере через PHP-библиотеку scssphp. Node.js нужен только разработчикам для сборки админ-панели.</p></details><details class="details custom-block"><summary>Можно ли использовать exDoc вместе со стандартными модулями OpenCart?</summary><p>Да. exDoc работает параллельно со стандартной системой модулей OpenCart. Вы можете использовать оба подхода одновременно.</p></details><details class="details custom-block"><summary>Повлияет ли exDoc на скорость сайта?</summary><p>exDoc включает многоуровневое кэширование и автоматически исключает ресурсы неактивных блоков. При правильной настройке кэша влияние на производительность минимально.</p></details><details class="details custom-block"><summary>Можно ли перенести блоки с одного сайта на другой?</summary><p>Да, но не всё сразу. Экспорт и импорт есть у блоков, рубрик и шаблонов — каждый переносится отдельно. Через экспорт быстрых настроек переносятся палитры, схемы, переменные, SCSS-стили, скрипты, SVG-спрайты, компоненты, глобальные поля и пресеты полей: выбранное копируется в буфер обмена и вставляется на другом сайте.</p><p>Категории, документы и коллекции — то есть сам контент — таким образом не переносятся.</p></details><details class="details custom-block"><summary>Какие версии OpenCart поддерживаются?</summary><p>exDoc работает с OpenCart 3.x. Требуется PHP 7.x и MySQL 5.7+ с поддержкой JSON-колонок.</p></details><h2 id="следующие-шаги" tabindex="-1">Следующие шаги <a class="header-anchor" href="#следующие-шаги" aria-label="Permalink to &quot;Следующие шаги&quot;">​</a></h2><ul><li><a href="./installation.html">Установка</a> — требования и пошаговая установка</li><li><a href="./interface.html">Обзор интерфейса</a> — структура админ-панели и навигация</li><li><a href="./first-steps.html">Первые шаги</a> — создание первого блока и страницы</li></ul>',8))])}const f=o(c,[["render",m]]);export{C as __pageData,f as default};
